def utc_now() -> dt.datetime:
    return dt.datetime.now(dt.timezone.utc)


def utc_iso() -> str:
    return utc_now().isoformat(timespec="milliseconds")


def local_iso() -> str:
    return dt.datetime.now().astimezone().isoformat(timespec="seconds")


def parse_iso(value: Optional[str]) -> Optional[dt.datetime]:
    if not value:
        return None
    try:
        parsed = dt.datetime.fromisoformat(value)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=dt.timezone.utc)
        return parsed
    except Exception:
        return None


def json_dumps(value: Any, *, pretty: bool = False) -> str:
    return json.dumps(value, ensure_ascii=False, indent=2 if pretty else None, separators=None if pretty else (",", ":"), default=str)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_text(text: str) -> str:
    return sha256_bytes(text.encode("utf-8"))


def b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")


def b64url_decode(text: str) -> bytes:
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def deep_merge(default: Any, current: Any) -> Any:
    """Merge user config over defaults while preserving unknown user keys."""
    if isinstance(default, dict) and isinstance(current, dict):
        merged = copy.deepcopy(default)
        for key, value in current.items():
            if key in merged:
                merged[key] = deep_merge(merged[key], value)
            else:
                merged[key] = copy.deepcopy(value)
        return merged
    return copy.deepcopy(current)


def nested_get(data: Mapping[str, Any], path: str, default: Any = None) -> Any:
    cur: Any = data
    for part in path.split("."):
        if not isinstance(cur, Mapping) or part not in cur:
            return default
        cur = cur[part]
    return cur


def nested_set(data: MutableMapping[str, Any], path: str, value: Any) -> None:
    parts = path.split(".")
    cur: MutableMapping[str, Any] = data
    for part in parts[:-1]:
        nxt = cur.get(part)
        if not isinstance(nxt, MutableMapping):
            nxt = {}
            cur[part] = nxt
        cur = nxt
    cur[parts[-1]] = value


def sanitize_filename(value: str, fallback: str = "meeting") -> str:
    value = re.sub(r"[<>:\"/\\|?*\x00-\x1f]", "_", (value or "").strip())
    value = re.sub(r"\s+", "_", value).strip("._ ")
    return (value[:80] or fallback)


def atomic_write_bytes(path: Path, data: bytes, *, backup: bool = False) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if backup and path.exists():
        BACKUP_DIR.mkdir(parents=True, exist_ok=True)
        stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
        shutil.copy2(path, BACKUP_DIR / f"{path.name}.{stamp}.bak")
    fd, tmp_name = tempfile.mkstemp(prefix=path.name + ".", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(data)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_name, path)
    except Exception:
        with contextlib.suppress(Exception):
            os.unlink(tmp_name)
        raise


def atomic_write_text(path: Path, text: str, *, backup: bool = False) -> None:
    atomic_write_bytes(path, text.encode("utf-8"), backup=backup)


def atomic_write_json(path: Path, data: Any, *, backup: bool = False) -> None:
    atomic_write_text(path, json_dumps(data, pretty=True) + "\n", backup=backup)


def read_json(path: Path, default: Any = None) -> Any:
    try:
        with path.open("r", encoding="utf-8-sig") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return copy.deepcopy(default)
    except Exception:
        return copy.deepcopy(default)


def append_jsonl(path: Path, item: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    line = json_dumps(dict(item)) + "\n"
    with path.open("a", encoding="utf-8", newline="\n") as fh:
        fh.write(line)
        fh.flush()
        # JSONL is the durable source of truth.  fsync keeps a sudden process or
        # machine failure from losing an already acknowledged transcript/event.
        with contextlib.suppress(OSError):
            os.fsync(fh.fileno())


def tail_jsonl(path: Path, limit: int = 200) -> List[Dict[str, Any]]:
    if not path.exists() or limit <= 0:
        return []
    items: Deque[Dict[str, Any]] = deque(maxlen=limit)
    try:
        with path.open("r", encoding="utf-8-sig", errors="replace") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                with contextlib.suppress(Exception):
                    obj = json.loads(line)
                    if isinstance(obj, dict):
                        items.append(obj)
    except Exception:
        return []
    return list(items)


def read_jsonl_after_seq(path: Path, after_seq: int, limit: int = 2000) -> List[Dict[str, Any]]:
    result: List[Dict[str, Any]] = []
    if not path.exists():
        return result
    try:
        with path.open("r", encoding="utf-8-sig", errors="replace") as fh:
            for line in fh:
                with contextlib.suppress(Exception):
                    obj = json.loads(line)
                    if int(obj.get("seq", 0)) > after_seq:
                        result.append(obj)
                        if len(result) >= limit:
                            break
    except Exception:
        pass
    return result


def human_bytes(num: Union[int, float]) -> str:
    n = float(num)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if abs(n) < 1024.0:
            return f"{n:.1f} {unit}"
        n /= 1024.0
    return f"{n:.1f} PB"


def bundle_files() -> Dict[str, bytes]:
    if not BUNDLE_B64 or BUNDLE_B64 == "__BUNDLE_B64__":
        return {}
    raw = base64.b64decode("".join(BUNDLE_B64.split()))
    files: Dict[str, bytes] = {}
    with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
        for info in zf.infolist():
            normalized = Path(info.filename)
            if info.is_dir() or normalized.is_absolute() or ".." in normalized.parts:
                continue
            files[str(normalized).replace("\\", "/")] = zf.read(info)
    return files


def bootstrap_embedded_files() -> Dict[str, Any]:
    """Create/update managed child files while preserving user modifications."""
    for folder in (DATA_DIR, MEETINGS_DIR, LOG_DIR, CACHE_DIR, BACKUP_DIR, PROMPTS_DIR, WEB_DIR, CERT_DIR):
        folder.mkdir(parents=True, exist_ok=True)
    old_manifest = read_json(MANIFEST_PATH, {}) or {}
    old_files = old_manifest.get("files", {}) if isinstance(old_manifest, dict) else {}
    new_manifest: Dict[str, Any] = {"bundle_version": BUNDLE_VERSION, "files": {}, "updated_at": utc_iso()}
    report = {"created": [], "updated": [], "preserved": [], "staged": []}
    for rel, content in bundle_files().items():
        dest = BASE_DIR / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        new_hash = sha256_bytes(content)
        previous_entry = old_files.get(rel, {}) if isinstance(old_files, dict) else {}
        previous_hash = previous_entry.get("hash") if isinstance(previous_entry, dict) else None
        current_hash = sha256_bytes(dest.read_bytes()) if dest.exists() else None
        managed = rel.startswith("web/") or rel.startswith("schemas/") or rel == "VERSION.json" or rel == "VERSION.txt" or rel.lower().endswith((".bat", ".ps1")) or rel in {"README.md", "requirements.txt", "requirements-asr-funasr.txt", "requirements-asr-whisper.txt", "test_meetingai.py"}
        if not dest.exists():
            atomic_write_bytes(dest, content)
            report["created"].append(rel)
        elif current_hash == new_hash:
            pass
        elif rel.startswith("web/") or rel.startswith("schemas/") or rel in {"VERSION.json", "VERSION.txt"}:
            # Version-coupled application assets are always synchronized with the Python entry file.
            atomic_write_bytes(dest, content)
            report["updated"].append(rel)
        elif managed and previous_hash and current_hash == previous_hash:
            atomic_write_bytes(dest, content)
            report["updated"].append(rel)
        elif rel.startswith("prompts/"):
            staged = dest.with_suffix(dest.suffix + ".default-new")
            atomic_write_bytes(staged, content)
            report["preserved"].append(rel)
            report["staged"].append(str(staged.relative_to(BASE_DIR)))
        elif managed:
            staged = dest.with_suffix(dest.suffix + ".new")
            atomic_write_bytes(staged, content)
            report["preserved"].append(rel)
            report["staged"].append(str(staged.relative_to(BASE_DIR)))
        else:
            report["preserved"].append(rel)
        new_manifest["files"][rel] = {"hash": new_hash}
    atomic_write_json(MANIFEST_PATH, new_manifest)
    return report



