SENSITIVITY_THRESHOLDS = {"low": 0.88, "balanced": 0.76, "high": 0.62}

def normalize_runtime_settings(value: Optional[Mapping[str, Any]]) -> Dict[str, Any]:
    out = copy.deepcopy(RUNTIME_SETTING_DEFAULTS)
    if isinstance(value, Mapping):
        for key in RUNTIME_SETTING_KEYS:
            if key in value:
                out[key] = copy.deepcopy(value[key])
    profile = str(out.get("scan_profile", "balanced"))
    if profile in SCAN_PROFILES and isinstance(value, Mapping) and "scan_profile" in value:
        for key, v in SCAN_PROFILES[profile].items():
            if key not in value:
                out[key] = v
    out["workspace_mode"] = str(out.get("workspace_mode", "meeting")) if str(out.get("workspace_mode", "meeting")) in {"meeting", "ambient"} else "meeting"
    out["layout_profile"] = str(out.get("layout_profile", "standard")) if str(out.get("layout_profile", "standard")) in {"standard", "assistant", "record", "intelligence"} else "standard"
    out["default_depth"] = str(out.get("default_depth", "standard")) if str(out.get("default_depth", "standard")) in {"quick", "standard", "deep"} else "standard"
    kbids = out.get("knowledge_base_ids", [])
    out["knowledge_base_ids"] = list(dict.fromkeys(re.sub(r"[^A-Za-z0-9_.-]+", "-", str(x)).strip("-")[:80] for x in kbids if str(x).strip()))[:20] if isinstance(kbids, list) else []
    out["question_radar_sensitivity"] = str(out.get("question_radar_sensitivity", "balanced")) if str(out.get("question_radar_sensitivity", "balanced")) in SENSITIVITY_THRESHOLDS else "balanced"
    qa = str(out.get("question_auto_action", "alert"))
    if qa == "full": qa = "standard"
    out["question_auto_action"] = qa if qa in {"off", "alert", "quick", "standard"} else "alert"
    out["scan_profile"] = profile if profile in {*SCAN_PROFILES, "custom"} else "balanced"
    out["live_poll_ms"] = max(300, min(10000, int(float(out.get("live_poll_ms", 1000)))))
    out["question_scan_seconds"] = max(1.0, min(120.0, float(out.get("question_scan_seconds", 4))))
    out["analysis_interval_seconds"] = max(5.0, min(300.0, float(out.get("analysis_interval_seconds", 15))))
    out["live_brief_seconds"] = max(2.0, min(30.0, float(out.get("live_brief_seconds", 2))))
    out["live_brief_min_chars"] = max(40, min(1200, int(out.get("live_brief_min_chars", 50))))
    out["analysis_min_chars"] = max(50, min(5000, int(out.get("analysis_min_chars", 220))))
    out["suggestion_interval_seconds"] = max(10.0, min(600.0, float(out.get("suggestion_interval_seconds", 30))))
    out["suggestion_min_chars"] = max(50, min(5000, int(out.get("suggestion_min_chars", 120))))
    out["manual_probe_window_seconds"] = max(15, min(120, int(out.get("manual_probe_window_seconds", 45))))
    out["ambient_idle_gap_minutes"] = max(5, min(240, int(out.get("ambient_idle_gap_minutes", 30))))
    out["topic_switch_mode"] = str(out.get("topic_switch_mode", "balanced")) if str(out.get("topic_switch_mode", "balanced")) in {"stable", "balanced", "sensitive"} else "balanced"
    out["topic_history_limit"] = max(5, min(100, int(out.get("topic_history_limit", 30))))
    for key in ("audio_auto_start", "asr_enabled", "save_recording", "analysis_enabled", "live_brief_enabled", "suggested_questions_enabled", "question_radar_enabled"):
        out[key] = bool(out.get(key))
    return out

def preset_catalog(config: "ConfigManager") -> Dict[str, Dict[str, Any]]:
    result = copy.deepcopy(BUILTIN_MEETING_PRESETS)
    custom = config.value("presets.custom", {}) or {}
    if isinstance(custom, Mapping):
        for key, item in custom.items():
            if not isinstance(item, Mapping):
                continue
            pid = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(key or item.get("id", ""))).strip("-")[:80]
            if not pid or pid in BUILTIN_MEETING_PRESETS:
                continue
            result[pid] = {
                "id": pid,
                "name": str(item.get("name") or pid)[:80],
                "description": str(item.get("description") or "")[:500],
                "builtin": False,
                "settings": normalize_runtime_settings(item.get("settings", {})),
            }
    return result

def resolve_preset(config: "ConfigManager", preset_id: str = "") -> Dict[str, Any]:
    catalog = preset_catalog(config)
    default_id = str(config.value("presets.default_id", "general") or "general")
    pid = str(preset_id or default_id)
    return copy.deepcopy(catalog.get(pid) or catalog.get(default_id) or BUILTIN_MEETING_PRESETS["general"])

def meeting_runtime_settings(state: Mapping[str, Any]) -> Dict[str, Any]:
    return normalize_runtime_settings(state.get("runtime_settings") if isinstance(state, Mapping) else None)

ANSWER_SCOPES = frozenset({"meeting", "knowledge", "rag", "web", "all"})
ANSWER_DEPTHS = frozenset({"quick", "standard", "deep"})
NOTE_SOURCES = frozenset({"meeting", "meeting_rag", "knowledge", "all"})

def normalize_answer_scope(value: Any, default: str = "knowledge") -> str:
    value = str(value or default)
    return value if value in ANSWER_SCOPES else default

def normalize_answer_depth(value: Any, default: str = "standard") -> str:
    value = str(value or default)
    return value if value in ANSWER_DEPTHS else default

def meeting_runtime_policy(state: Mapping[str, Any], config: Optional["ConfigManager"] = None) -> Dict[str, Any]:
    raw = state.get("runtime_policy", {}) if isinstance(state, Mapping) else {}
    if not isinstance(raw, Mapping): raw = {}
    fallback_scope = config.value("assistant.default_scope", "knowledge") if config is not None else "knowledge"
    fallback_depth = meeting_runtime_settings(state).get("default_depth", config.value("assistant.default_depth", "standard") if config is not None else "standard")
    try: version = max(1, int(raw.get("policy_version", 1) or 1))
    except Exception: version = 1
    return {"answer_scope": normalize_answer_scope(raw.get("answer_scope"), normalize_answer_scope(fallback_scope)), "policy_version": version, "default_depth": normalize_answer_depth(raw.get("default_depth"), normalize_answer_depth(fallback_depth))}

