class ConfigError(ValueError):
    pass




def migrate_config_data(raw: Mapping[str, Any]) -> Dict[str, Any]:
    """Explicit, idempotent config migration. Supports schema 10/11/12/13 -> 14."""
    data = copy.deepcopy(dict(raw or {}))
    if not data:
        return data
    try:
        version = int(data.get("schema_version", 0) or 0)
    except Exception as exc:
        raise ConfigError("config schema_version is invalid") from exc
    if str(data.get("schema", "")) != "meetingai.config":
        raise ConfigError("unsupported config schema")
    if version == 10:
        data.setdefault("meeting", {}).setdefault("analysis_snapshot_limit", 120)
        data.setdefault("notes", {}).setdefault("post_meeting_async", True)
        data["schema_version"] = 11
        version = 11
    if version == 11:
        ui = data.setdefault("ui", {})
        ui.setdefault("workspace_collapsed_pane", "")
        ui.setdefault("workspace_collapsed_width_px", 44)
        data["schema_version"] = 12
        version = 12
    if version == 12:
        data.setdefault("audio", {}).setdefault("import", copy.deepcopy(DEFAULT_CONFIG.get("audio", {}).get("import", {})))
        data.setdefault("environment", copy.deepcopy(DEFAULT_CONFIG.get("environment", {})))
        data["schema_version"] = 13
        version = 13
    if version == 13:
        data.setdefault("asr", {}).setdefault("semantic", copy.deepcopy(DEFAULT_CONFIG.get("asr", {}).get("semantic", {})))
        data.setdefault("ai", {}).setdefault("task_providers", {}).setdefault("asr_semantic_annotation", "")
        data["schema_version"] = 14
        version = 14
    compat = data.setdefault("updates", {}).setdefault("compatibility", {})
    compat["current_schema"] = 14
    compat["minimum_migratable_schema"] = 10
    if version != CONFIG_SCHEMA_VERSION:
        raise ConfigError(f"MeetingAI {APP_VERSION} supports config schema 10/11/12/13 migration or current schema {CONFIG_SCHEMA_VERSION}; got {version}")
    data["app_version"] = APP_VERSION
    return data

class ConfigManager:
    def __init__(self, path: Path = CONFIG_PATH):
        self.path = path
        self._lock = threading.RLock()
        self._config: Dict[str, Any] = {}
        self.load()

    def load(self) -> Dict[str, Any]:
        with self._lock:
            raw = read_json(self.path, {}) or {}
            migrated = migrate_config_data(raw) if raw else raw
            merged = deep_merge(DEFAULT_CONFIG, migrated)
            self.validate(merged)
            self._config = merged
            if not self.path.exists() or raw != merged:
                atomic_write_json(self.path, merged, backup=self.path.exists())
            return copy.deepcopy(self._config)

    def get(self) -> Dict[str, Any]:
        with self._lock:
            return copy.deepcopy(self._config)

    def value(self, path: str, default: Any = None) -> Any:
        with self._lock:
            return copy.deepcopy(nested_get(self._config, path, default))

    def update(self, new_config: Mapping[str, Any]) -> Dict[str, Any]:
        with self._lock:
            candidate = copy.deepcopy(dict(new_config))
            candidate["schema"] = "meetingai.config"
            candidate["schema_version"] = CONFIG_SCHEMA_VERSION
            candidate["app_version"] = APP_VERSION
            merged = deep_merge(DEFAULT_CONFIG, candidate)
            self.validate(merged)
            atomic_write_json(self.path, merged, backup=True)
            self._config = merged
            self._trim_config_backups()
            return copy.deepcopy(merged)

    def patch(self, path: str, value: Any) -> Dict[str, Any]:
        cfg = self.get()
        nested_set(cfg, path, value)
        return self.update(cfg)

    def validate(self, cfg: Mapping[str, Any]) -> None:
        if str(cfg.get("schema", "meetingai.config")) != "meetingai.config":
            raise ConfigError("config schema must be meetingai.config")
        if int(cfg.get("schema_version", 0) or 0) != CONFIG_SCHEMA_VERSION:
            raise ConfigError(f"config schema_version must be {CONFIG_SCHEMA_VERSION}")
        try:
            port = int(nested_get(cfg, "server.port", 0))
            https_port = int(nested_get(cfg, "server.https_port", 0))
        except Exception as exc:
            raise ConfigError("server ports must be integers") from exc
        if not 1 <= port <= 65535 or not 1 <= https_port <= 65535:
            raise ConfigError("server port must be between 1 and 65535")
        server_mode = str(nested_get(cfg, "server.mode", "auto"))
        if server_mode not in {"auto", "http", "https"}:
            raise ConfigError("server.mode must be auto/http/https")
        proxy_mode = str(nested_get(cfg, "server.proxy_mode", "direct"))
        if proxy_mode not in {"direct", "forwarded", "proxy_v2"}:
            raise ConfigError("server.proxy_mode must be direct/forwarded/proxy_v2")
        cidrs = nested_get(cfg, "server.trusted_proxy_cidrs", [])
        if not isinstance(cidrs, list):
            raise ConfigError("server.trusted_proxy_cidrs must be an array")
        for value in cidrs:
            try:
                ipaddress.ip_network(str(value), strict=False)
            except Exception as exc:
                raise ConfigError(f"invalid trusted proxy CIDR: {value}") from exc
        response_headers = nested_get(cfg, "server.response_headers", {})
        if not isinstance(response_headers, Mapping):
            raise ConfigError("server.response_headers must be an object")
        root_path = str(nested_get(cfg, "server.root_path", "") or "")
        if root_path and (not root_path.startswith("/") or (len(root_path) > 1 and root_path.endswith("/"))):
            raise ConfigError("server.root_path must start with / and must not end with /")
        if not 64 <= int(nested_get(cfg, "server.proxy_v2_max_header_bytes", 512)) <= 4096:
            raise ConfigError("server.proxy_v2_max_header_bytes must be 64..4096")

        context_cfg = nested_get(cfg, "ai.context", {})
        if not isinstance(context_cfg, Mapping):
            raise ConfigError("ai.context must be an object")
        for key in ("default_max_tokens", "quick_qa_tokens", "analysis_tokens", "segment_summary_tokens", "final_summary_tokens", "deep_analysis_tokens"):
            if int(context_cfg.get(key, 0) or 0) < 2048:
                raise ConfigError(f"ai.context.{key} must be at least 2048 tokens")
        reserve = int(context_cfg.get("reserve_output_tokens", 8192) or 8192)
        if reserve < 256:
            raise ConfigError("ai.context.reserve_output_tokens must be at least 256")

        assignment_mode = str(nested_get(cfg, "ai.assignment_mode", "unified"))
        if assignment_mode not in {"unified", "custom"}:
            raise ConfigError("invalid ai.assignment_mode")
        scheduler_mode = str(nested_get(cfg, "ai.scheduler_mode", "auto"))
        if scheduler_mode not in {"auto", "serial", "parallel"}:
            raise ConfigError("invalid ai.scheduler_mode")
        worker_count = int(nested_get(cfg, "ai.worker_count", 2))
        if not 1 <= worker_count <= 8:
            raise ConfigError("ai.worker_count must be between 1 and 8")

        providers = nested_get(cfg, "ai.providers", {})
        if not isinstance(providers, Mapping) or not providers:
            raise ConfigError("at least one AI provider must be configured")
        for key, provider in providers.items():
            if not isinstance(provider, Mapping):
                raise ConfigError(f"AI provider {key!r} is invalid")
            ptype = str(provider.get("type", "openai_compatible"))
            if ptype not in {"ollama_native", "openai_compatible", "mock"}:
                raise ConfigError(f"unsupported provider type: {ptype}")
            enabled = bool(provider.get("enabled", True))
            if enabled and ptype in {"ollama_native", "openai_compatible"} and not str(provider.get("base_url", "")).strip():
                raise ConfigError(f"enabled provider {key!r} requires base_url")
            concurrency = int(provider.get("max_concurrency", 1))
            if not 1 <= concurrency <= 8:
                raise ConfigError(f"provider {key!r} max_concurrency must be between 1 and 8")
            if int(provider.get("max_context_tokens", 65536) or 65536) < 2048:
                raise ConfigError(f"provider {key!r} max_context_tokens must be >= 2048")
            if int(provider.get("max_output_tokens", 4096) or 4096) < 64:
                raise ConfigError(f"provider {key!r} max_output_tokens must be >= 64")
            if ptype == "ollama_native" and int(provider.get("ollama_num_ctx", provider.get("max_context_tokens", 65536)) or 65536) < 2048:
                raise ConfigError(f"provider {key!r} ollama_num_ctx must be >= 2048")
            capability = str(provider.get("reasoning_capability", "auto") or "auto")
            if capability not in {"auto", "none", "ollama_think", "openai_effort"}:
                raise ConfigError(f"provider {key!r} reasoning_capability is invalid")
            if float(provider.get("timeout_seconds", 180) or 180) < 1:
                raise ConfigError(f"provider {key!r} timeout_seconds must be >= 1")
            for field_name in ("headers", "query_params", "extra_body"):
                value = provider.get(field_name, {})
                if value is not None and not isinstance(value, Mapping):
                    raise ConfigError(f"provider {key!r} {field_name} must be an object")
            fallback = str(provider.get("fallback_provider", "") or "")
            if fallback and fallback not in providers:
                raise ConfigError(f"provider {key!r} fallback {fallback!r} does not exist")
            if fallback == key:
                raise ConfigError(f"provider {key!r} cannot fall back to itself")
            if fallback and not bool(providers[fallback].get("enabled", True)):
                raise ConfigError(f"provider {key!r} fallback {fallback!r} must be enabled")

        default_provider = str(nested_get(cfg, "ai.default_provider", "") or "")
        if default_provider not in providers or not bool(providers[default_provider].get("enabled", True)):
            raise ConfigError("ai.default_provider must reference an enabled provider")
        task_providers = nested_get(cfg, "ai.task_providers", {})
