        for start_key in providers:
            seen: Set[str] = set(); current = str(start_key)
            while current:
                if current in seen:
                    raise ConfigError(f"AI provider fallback cycle detected at {current!r}")
                seen.add(current)
                provider = providers.get(current, {})
