    async def suggest_questions(self, meeting_id: str, transcript_items: Sequence[Mapping[str, Any]]) -> List[str]:
        provider_name = self.provider_for("suggested_questions")
        state = self.store.load(meeting_id)
        recent_text = self.context.transcript_text(transcript_items)
        recent_chat = self.store.recent_chat(meeting_id, 8)
        asked = [str(x.get("text", "")) for x in recent_chat if str(x.get("role", "")) == "user"][-5:]
        messages = self.system_messages(self.prompts.read("suggested_questions"), meeting_id)
        messages.append({"role": "user", "content": "<meeting_context>\n当前议题：" + str(state.get("current_topic", "")) + "\n最近对话：\n" + trim_text_to_tokens(recent_text, 2800, keep_tail=True) + "\n最近用户问题：" + json_dumps(asked) + "\n</meeting_context>\n只输出 JSON：{\"questions\":[\"问题1\",\"问题2\",\"问题3\"]}"})
        async def invoke() -> Dict[str, Any]:
            return await self.client.chat(provider_name, messages, temperature=0.15, max_tokens=500, response_json=True, task_type="suggested_questions")
        result = await self.scheduler.submit("suggestion", provider_name, invoke, priority="suggestion", coalesce_key=f"suggestions:{meeting_id}", wait=True)
        obj = extract_json_object(result.get("text", "")) or {}
        values = obj.get("questions", []) if isinstance(obj, Mapping) else []
        cleaned: List[str] = []
        for value in values if isinstance(values, list) else []:
            q = re.sub(r"\s+", " ", str(value or "")).strip()[:120]
            if q and q not in cleaned: cleaned.append(q)
        return cleaned[:5]

