        async def invoke(): return await self.client.chat(provider_name,messages,temperature=0.1,max_tokens=3500,task_type="timeline_analysis")
        result=await self.scheduler.submit("timeline_analysis",provider_name,invoke,priority="timeline",coalesce_key=f"timeline:{meeting_id}",wait=True)
