    async def add_manual_note(self, meeting_id: str, text: str, *, title: str = "", operation_id: str = "") -> Dict[str, Any]:
        text = str(text or "").strip()
        if not text: raise ValueError("note is empty")
        max_chars = int(self.config.value("notes.max_manual_note_chars", 12000))
        if len(text) > max_chars: raise ValueError("note is too long")
        if operation_id and self._operation_seen(meeting_id, operation_id): return {"duplicate": True, "state": self.store.load(meeting_id)}
        item = {"schema":"meetingai.note","schema_version":NOTES_SCHEMA_VERSION,"id":"N-"+uuid.uuid4().hex[:10],"created_at":utc_iso(),"type":"manual","title":str(title or "手工笔记")[:120],"text":text,"source":"user"}
        self.store.append_note(meeting_id, item)
        state = self.store.patch(meeting_id, lambda st: st.__setitem__("notes_count", int(st.get("notes_count",0))+1))
        if operation_id: self._record_operation(meeting_id, operation_id)
        await self.event_hub.publish(meeting_id, "note_manual", {"note":item,"text":text})
        return {"note":item,"state":state,"duplicate":False}

