    def _operation_seen(self, meeting_id: str, operation_id: str) -> bool:
        if not operation_id: return False
        state=self.store.load(meeting_id); return operation_id in set(str(x) for x in state.get("client_operation_ids", []))

    def _record_operation(self, meeting_id: str, operation_id: str) -> None:
        if not operation_id: return
