    @app.post("/api/meetings/{meeting_id}/audio")
    async def upload_audio_chunk(meeting_id: str, request: Request, session: SessionInfo = Depends(auth_write)) -> Dict[str, Any]:
        sid = str(request.headers.get("x-audio-session", "")).strip(); mime = str(request.headers.get("content-type", "audio/webm")).split("; charset=", 1)[0].strip()
        try: seq = int(request.headers.get("x-audio-seq", "0")); duration_ms = int(request.headers.get("x-audio-duration-ms", "0"))
        except ValueError: raise HTTPException(status_code=400, detail="invalid audio sequence/duration")
        if not sid or seq < 1 or duration_ms < 100: raise HTTPException(status_code=400, detail="missing audio session/sequence/duration")
        body = await request.body()
        status = {"pending_chunks": request.headers.get("x-audio-pending", "0"), "buffered_seconds": request.headers.get("x-audio-buffered-seconds", "0"), "level_db": request.headers.get("x-audio-level-db", "-120"), "visibility": request.headers.get("x-audio-visibility", "visible"), "client_network_state": request.headers.get("x-audio-network", "online"), "speech": request.headers.get("x-audio-speech", "1") not in {"0","false","False"}}
        with contextlib.suppress(Exception): status["pending_chunks"] = int(status["pending_chunks"]); status["buffered_seconds"] = float(status["buffered_seconds"]); status["level_db"] = float(status["level_db"])
        try:
            result = await runtime.audio.ingest(sid, seq, duration_ms, body, mime_type=mime, client_status=status, expected_meeting_id=meeting_id)
        except AudioBackpressure as exc:
            raise HTTPException(status_code=429, detail={"code": "audio_backpressure", "message": str(exc), "retry_after_ms": exc.retry_after_ms})
        except MeetingConflict as exc:
            code = str(exc)
            message = {"audio_session_inactive": "音频会话已失效，浏览器将尝试自动恢复。", "audio_session_wrong_meeting": "音频会话与当前会议不匹配。"}.get(code, code)
            raise HTTPException(status_code=409, detail={"code": code, "message": message, "recoverable": code == "audio_session_inactive"})
        except ValueError as exc:
            raise HTTPException(status_code=400, detail={"code": "invalid_audio_chunk", "message": str(exc)})
        return {"ok": True, **result, "server_time": utc_iso()}


