    @app.patch("/api/meetings/{meeting_id}/transcript/{transcript_id}")
    async def patch_transcript(meeting_id: str, transcript_id: str, request: Request, session: SessionInfo = Depends(auth_write)) -> Dict[str, Any]:
        body = await read_body(request); operation_id = str(body.pop("operation_id", "") or "")
        if operation_id and runtime.meetings._operation_seen(meeting_id, operation_id):
            current = next((x for x in runtime.store.recent_transcript(meeting_id, 5000) if str(x.get("id", "")) == transcript_id), None)
            return {"ok": True, "duplicate": True, "transcript": current}
        patch: Dict[str, Any] = {}
        if "quality" in body:
            quality = str(body.get("quality", "normal"));
            if quality not in {"normal", "uncertain", "wrong"}: raise HTTPException(status_code=400, detail="invalid transcript quality")
            patch["quality"] = quality
        if "ignored" in body: patch["ignored"] = bool(body.get("ignored"))
        if "display_text" in body: patch["display_text"] = str(body.get("display_text", ""))[:10000]
        if not patch: raise HTTPException(status_code=400, detail="empty transcript patch")
        item = runtime.store.patch_transcript(meeting_id, transcript_id, patch)
        if operation_id: runtime.meetings._record_operation(meeting_id, operation_id)
        await runtime.event_hub.publish(meeting_id, "transcript_updated", {"transcript": item})
        return {"ok": True, "duplicate": False, "transcript": item}

