    @app.patch("/api/meetings/{meeting_id}/items/{kind}/{item_id}")
    async def patch_item(meeting_id: str, kind: str, item_id: str, request: Request, session: SessionInfo = Depends(auth_write)) -> Dict[str, Any]:
        if kind not in {"decisions", "actions", "questions", "risks", "facts"}:
            raise HTTPException(status_code=400, detail="invalid item kind")
        body = await read_body(request)
        allowed_fields = {"text", "owner", "due", "status", "priority"}
        def mutate(state: Dict[str, Any]) -> None:
            for item in state.get(kind, []):
                if isinstance(item, dict) and item.get("id") == item_id:
                    for key, value in body.items():
                        if key in allowed_fields:
                            item[key] = value
                    item["updated_at"] = utc_iso()
                    return
            raise MeetingNotFound(item_id)
        state = runtime.store.patch(meeting_id, mutate)
        await runtime.event_hub.publish(meeting_id, "item_updated", {"kind": kind, "item_id": item_id, "patch": body, "state": state})
        return {"ok": True, "meeting": runtime.store.load(meeting_id)}

    @app.delete("/api/meetings/{meeting_id}")
    async def delete_meeting(meeting_id: str, request: Request, session: SessionInfo = Depends(auth_write)) -> Dict[str, Any]:
        active = runtime.meetings.find_active()
        if active and active.get("id") == meeting_id:
            raise MeetingConflict("end the active meeting before deleting it")
        state=runtime.store.load(meeting_id); jobs=state.get("post_meeting_jobs",{}) if isinstance(state.get("post_meeting_jobs"),Mapping) else {}
        if str(jobs.get("overall","idle")) in {"queued","running"}:
            raise MeetingConflict("AI整理中，会议暂时锁定，完成后可删除")
        with contextlib.suppress(Exception): runtime.store.patch(meeting_id, lambda s: s.__setitem__("deleting", True))
        runtime.store.delete(meeting_id)
        return {"ok": True}

