    @app.post("/api/admin/presets")
    async def create_preset(request: Request, session: SessionInfo = Depends(auth_write)) -> Dict[str, Any]:
        body = await read_body(request); name = str(body.get("name", "")).strip()
        if not name: raise HTTPException(status_code=400, detail="preset name is required")
        requested = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(body.get("id", "") or name)).strip("-").lower()[:80]
        pid = requested or ("preset-" + uuid.uuid4().hex[:8])
        if pid in BUILTIN_MEETING_PRESETS or pid in (runtime.config.value("presets.custom", {}) or {}): pid = "preset-" + uuid.uuid4().hex[:8]
        cfg = runtime.config.get(); custom = nested_get(cfg, "presets.custom", {}) or {}; custom = dict(custom)
        custom[pid] = {"id": pid, "name": name[:80], "description": str(body.get("description", ""))[:500], "settings": normalize_runtime_settings(body.get("settings", {}))}
        nested_set(cfg, "presets.custom", custom); runtime.config.update(cfg)
        return {"ok": True, "preset": preset_catalog(runtime.config)[pid]}

