def run_parent_self_test() -> int:
    with tempfile.TemporaryDirectory(prefix="meetingai-selftest-") as tmp:
        env = os.environ.copy()
        env["MEETINGAI_HOME"] = tmp
        env["MEETINGAI_TEST_MODE"] = "1"
        cmd = [sys.executable, str(Path(__file__).resolve()), "--internal-self-test", "--no-browser"]
        proc = subprocess.run(cmd, env=env, text=True, capture_output=True, timeout=180)
        print(proc.stdout)
        if proc.stderr:
            print(proc.stderr, file=sys.stderr)
        return proc.returncode


async def run_internal_self_test(runtime: RuntimeContainer) -> Dict[str, Any]:
    report: Dict[str, Any] = {"ok": True, "checks": [], "base_dir": str(BASE_DIR)}

    def check(name: str, condition: bool, detail: Any = None) -> None:
        report["checks"].append({"name": name, "ok": bool(condition), "detail": detail})
        if not condition:
            report["ok"] = False

    check("bootstrap_config", CONFIG_PATH.exists())
    check("bootstrap_prompts", all(runtime.prompts.path(x).exists() for x in PromptManager.PROMPT_NAMES))
    initial_password = runtime.secrets.initial_password or FIRST_PASSWORD_PATH.read_text(encoding="utf-8").split("Password: ", 1)[1].splitlines()[0]
    credential = runtime.secrets.verify(initial_password)
    check("password_verify", bool(credential))
    extra = runtime.secrets.add_password("测试共享密码", "second-pass-123")
    check("multi_password", bool(runtime.secrets.verify("second-pass-123")) and len(runtime.secrets.list_passwords()) == 2)
    token, session = runtime.auth.create_token(True, str(credential.get("id")), str(credential.get("label")))
    check("session_roundtrip", runtime.auth.parse_token(token) is not None)
    check("csrf_roundtrip", runtime.auth.verify_csrf(session, runtime.auth.csrf_token(session)))
    check("json_parser", extract_json_object("```json\n{\"ok\":true}\n```") == {"ok": True})
    long_text = "中文会议内容" * 5000
    trimmed = trim_text_to_tokens(long_text, 1000)
    check("context_trim", estimate_tokens(trimmed) <= 1250, estimate_tokens(trimmed))
    check("scheduler_auto_single_provider_linear", runtime.scheduler.desired_worker_count() == 1, runtime.scheduler.desired_worker_count())
    catalog = preset_catalog(runtime.config)
    check("builtin_presets", all(x in catalog for x in ("general", "daily", "rapid_answer", "assistant_record", "executive")), list(catalog))
    check("network_health_defaults", runtime.config.value("network_health.ping_interval_seconds", 0) == 2.0 and runtime.config.value("network_health.average_window_seconds", 0) == 10.0 and runtime.config.value("network_health.offline_after_seconds", 0) == 10.0 and runtime.config.value("network_health.warning_ms", 0) == 10000)
    normalized = normalize_runtime_settings({"scan_profile":"realtime","default_depth":"deep","question_radar_sensitivity":"high"})
    check("runtime_normalization", normalized.get("live_poll_ms")==500 and normalized.get("default_depth")=="deep" and normalized.get("question_radar_sensitivity")=="high")

    await runtime.start()
    try:
        meeting = await runtime.meetings.create("自动测试会议", "测试", ["A", "B"], "测试背景", False, preset_id="daily")
        meeting_id = meeting["id"]
        check("meeting_create", runtime.store.paths(meeting_id)["state"].exists(), meeting_id)
        check("meeting_preset_create", meeting.get("preset_id") == "daily" and meeting_runtime_settings(meeting).get("scan_profile") == "fast", meeting.get("preset_id"))
        switched = await runtime.meetings.switch_preset(meeting_id, "rapid_answer")
        check("preset_hot_switch", switched.get("preset_id") == "rapid_answer" and meeting_runtime_settings(switched).get("question_auto_action") == "quick")
        overridden = await runtime.meetings.patch_runtime_settings(meeting_id,{"question_auto_action":"alert","default_depth":"deep","scan_profile":"balanced"})
        check("runtime_hot_override", overridden.get("preset_modified") is True and meeting_runtime_settings(overridden).get("default_depth")=="deep" and meeting_runtime_settings(overridden).get("live_poll_ms")==1000)
        policy_before=meeting_runtime_policy(overridden,runtime.config);policy_state=await runtime.meetings.patch_runtime_policy(meeting_id,{"answer_scope":"meeting"});policy_after=meeting_runtime_policy(policy_state,runtime.config)
        check("global_policy_version",policy_after["answer_scope"]=="meeting" and policy_after["policy_version"]==policy_before["policy_version"]+1,policy_after)
        restored = await runtime.meetings.switch_preset(meeting_id, "general")
        check("preset_restore", restored.get("preset_modified") is False and restored.get("preset_id") == "general")
        audio_result = await runtime.meetings.start_recording(meeting_id, client_id="selftest", client_label="SelfTest Browser")
        audio_session = audio_result["audio_session"]
        chunk_result = await runtime.audio.ingest(str(audio_session["session_id"]), 1, 1800, b"mock-browser-audio", mime_type="audio/webm", client_status={"speech": True})
        await runtime.asr.flush(timeout=5)
        check("browser_audio_ingest", chunk_result.get("seq") == 1 and int(runtime.audio.stats.get("chunks", 0)) >= 1)
        await runtime.meetings.stop_recording(meeting_id)


        item = await runtime.meetings.add_transcript(meeting_id, {"raw_text": "这是第一条测试记录，决定使用 Ollama。老师接着要求你解释为什么选择 Ollama。", "display_text": "这是第一条测试记录，决定使用 Ollama。老师接着要求你解释为什么选择 Ollama。", "speaker": "A", "source": "test", "start_seconds": 1.2})
        check("transcript_append", item.get("id", "").startswith("T-"))
        detected = await runtime.ai.detect_question(meeting_id, [item], priority="manual")
        check("semantic_question_detection", detected.get("needs_response") is True and "recommended_scope" not in detected, detected)
        suggested = await runtime.ai.suggest_questions(meeting_id, [item])
        check("suggested_questions_service", len(suggested) == 3 and all(bool(x) for x in suggested), suggested)
        probe = await runtime.meetings.probe_questions(meeting_id, 45)
        detected_item = probe.get("question") or {}
        check("active_question_probe", probe.get("detected") is True and str(detected_item.get("id", "")).startswith("DQ-"), detected_item)
        if detected_item.get("id"):
            answered_q = await runtime.meetings.answer_detected_question(meeting_id,str(detected_item["id"]),depth="quick")
            check("detected_question_answer", answered_q.get("message", {}).get("role") == "assistant" and any(str(q.get("status")) == "answered" for q in answered_q.get("state", {}).get("detected_questions", []) if isinstance(q, Mapping)))
            repeated_probe = await runtime.meetings.probe_questions(meeting_id, 45)
            repeated_item = repeated_probe.get("question") or {}
            check("answered_question_can_reappear", repeated_probe.get("detected") is True and repeated_item.get("id") and repeated_item.get("id") != detected_item.get("id") and repeated_item.get("status") == "new", repeated_item)
        await runtime.meetings._run_live_brief(meeting_id,[item])
        brief_state=runtime.store.load(meeting_id)
        check("live_brief_updates_topic", brief_state.get("current_topic")=="测试议题" and brief_state.get("current_topic_source")=="live_brief", {"topic":brief_state.get("current_topic"),"brief":brief_state.get("live_brief")})
        answer = await runtime.meetings.ask(meeting_id,"刚才决定使用什么？",depth="deep")
        check("mock_quick_answer",answer.get("role")=="assistant" and bool(answer.get("text")),answer.get("text"))
        check("answer_policy_snapshot",answer.get("scope")=="meeting" and int(answer.get("policy_version",0))>=2 and answer.get("depth")=="deep",{k:answer.get(k) for k in ("scope","policy_version","depth")})
        check("reasoning_metadata",isinstance(answer.get("reasoning"),Mapping) and answer["reasoning"].get("requested") is True,answer.get("reasoning"))

        system_messages = runtime.ai.system_messages(runtime.prompts.read("quick_qa"))
        check(
            "prompt_reinjection",
            len(system_messages) == 1 and system_messages[0].get("role") == "system"
            and "<base_system_rules>" in system_messages[0].get("content", "")
            and "<tool_rules>" in system_messages[0].get("content", ""),
        )

        bad_cfg = runtime.config.get()
        bad_cfg["ai"]["providers"]["fallback_a"] = {
            "enabled": True, "type": "mock", "model": "a", "base_url": "",
            "headers": {}, "query_params": {}, "extra_body": {},
            "timeout_seconds": 30, "connect_timeout_seconds": 3,
            "max_concurrency": 1, "max_context_tokens": 65536,
            "max_output_tokens": 1024, "fallback_provider": "fallback_b",
        }
        bad_cfg["ai"]["providers"]["fallback_b"] = {
            "enabled": True, "type": "mock", "model": "b", "base_url": "",
            "headers": {}, "query_params": {}, "extra_body": {},
            "timeout_seconds": 30, "connect_timeout_seconds": 3,
            "max_concurrency": 1, "max_context_tokens": 65536,
            "max_output_tokens": 1024, "fallback_provider": "fallback_a",
        }
        cycle_rejected = False
        try:
            runtime.config.validate(bad_cfg)
        except ConfigError:
            cycle_rejected = True
        check("provider_fallback_cycle_rejected", cycle_rejected)
        proxy_header = PROXY_V2_SIGNATURE + bytes([0x21, 0x11]) + struct.pack("!H", 12) + socket.inet_pton(socket.AF_INET, "192.0.2.10") + socket.inet_pton(socket.AF_INET, "198.51.100.20") + struct.pack("!HH", 12345, 443)
        reader = asyncio.StreamReader(); reader.feed_data(proxy_header); reader.feed_eof()
        parsed_proxy = await read_proxy_v2_header(reader, 1.0, 512)
        check("proxy_v2_parse", parsed_proxy.get("source_ip") == "192.0.2.10" and parsed_proxy.get("source_port") == 12345)

        patch = {
            "current_topic": "部署方案", "summary_update": "讨论了本地部署。",
            "decisions": [{"text": "使用 Ollama"}], "actions": [{"text": "测试模型", "owner": "A"}],
            "questions": [], "risks": [], "facts": [],
        }
        state = runtime.meetings.apply_analysis_patch(meeting_id, patch, [item])
        check("state_patch", len(state.get("decisions", [])) == 1 and len(state.get("actions", [])) == 1)

        # Proactive mode is deliberately thresholded and only invokes search in
        # explicit proactive search mode. This checks the full event path.
        cfg_before = runtime.config.get()
        cfg_proactive = copy.deepcopy(cfg_before)
        cfg_proactive["search"]["mode"] = "proactive"
        cfg_proactive["meeting"]["proactive_enabled"] = True
        cfg_proactive["meeting"]["proactive_sensitivity"] = 0.5
        cfg_proactive["meeting"]["proactive_min_interval_seconds"] = 10
        runtime.config.update(cfg_proactive)
        original_analyze = runtime.ai.analyze

        async def fake_analyze(_meeting_id: str, _items: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
            return {
                "current_topic": "版本核实", "summary_update": "需要核实版本信息。",
                "decisions": [], "actions": [], "questions": [], "risks": [], "facts": [],
                "need_search": True, "search_query": "MeetingAI self test current version",
                "importance": 0.9, "proactive_message": "建议联网核实当前版本。",
            }

        runtime.ai.analyze = fake_analyze  # type: ignore[assignment]
        try:
            await runtime.meetings._run_analysis(meeting_id, [item])
        finally:
            runtime.ai.analyze = original_analyze  # type: ignore[assignment]
            runtime.config.update(cfg_before)
        all_events = runtime.store.events_after(meeting_id, 0, 5000)
        check("proactive_search_event", any(x.get("type") == "proactive_search" for x in all_events))
        seqs = [int(x.get("seq", 0)) for x in all_events if int(x.get("seq", 0)) > 0]
        check("event_sequence_replay", bool(seqs) and seqs == sorted(set(seqs)), seqs[-5:])

        ended = await runtime.meetings.end(meeting_id)
        check("meeting_end", ended.get("status") == "finished")
        for _ in range(100):
            await asyncio.sleep(0.05)
            current = runtime.store.load(meeting_id)
            if current.get("final_summary_status") in {"complete", "failed"}:
                break
        current = runtime.store.load(meeting_id)
        check("final_summary", current.get("final_summary_status") == "complete", current.get("final_summary_status"))
        zip_path, _ = runtime.store.export(meeting_id, "zip")
        check("export_zip", zip_path.exists() and zipfile.is_zipfile(zip_path), str(zip_path))
        index_items = runtime.store.list()
        check("history_index", any(x.get("id") == meeting_id for x in index_items))
        diagnostic = await runtime.diagnostics.full()
        check("diagnostics", isinstance(diagnostic.get("checks"), list) and len(diagnostic["checks"]) >= 5)
    finally:
        await runtime.stop()
    return report


def reset_admin_password() -> str:
    manager = SecretManager(); password = "Meet-" + secrets.token_urlsafe(9).replace("-", "A").replace("_", "B")[:12]
    manager.data["passwords"] = [{"id": "main-" + uuid.uuid4().hex[:8], "label": "主密码", "enabled": True, "password": manager.hash_password(password), "created_at": utc_iso()}]
    manager.data["auth_version"] = int(manager.data.get("auth_version", 1)) + 1; manager.data["session_secret"] = b64url_encode(secrets.token_bytes(32)); manager.save()
    atomic_write_text(FIRST_PASSWORD_PATH, f"Password: {password}\n")
    return password


def parse_args(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="MeetingAI single-file meeting assistant")
    parser.add_argument("--host", help="override bind host for this run")
    parser.add_argument("--port", type=int, help="override bind port for this run")
    parser.add_argument("--https", action="store_true", help="prefer HTTPS; falls back to HTTP with a warning if ca.pem/ca.key are missing")
    parser.add_argument("--http", action="store_true", help="force HTTP even when HTTPS is enabled in config")
    parser.add_argument("--no-browser", action="store_true", help="do not open a browser automatically")
    parser.add_argument("--install-core", action="store_true", help="install core Python dependencies")
    parser.add_argument("--install-deps", choices=["core","funasr","faster-whisper","all"], help="install/repair MeetingAI Python dependencies; Python itself is never installed")
    parser.add_argument("--self-test", action="store_true", help="run isolated built-in tests")
    parser.add_argument("--internal-self-test", action="store_true", help=argparse.SUPPRESS)
    parser.add_argument("--doctor", action="store_true", help="run diagnostics in the console and exit")
    parser.add_argument("--reset-password", action="store_true", help="reset administrator password and exit")
    parser.add_argument("--test-mode", action="store_true", help=argparse.SUPPRESS)
    return parser.parse_args(argv)


def main(argv: Optional[Sequence[str]] = None) -> int:
    global RUNTIME
    args = parse_args(argv)
    report = bootstrap_embedded_files()
    if args.install_core:
        ensure_core_dependencies(auto_install=True)
        print("Core dependencies installed.")
        return 0
    if args.install_deps:
        cfg=ConfigManager(); envm=EnvironmentManager(cfg)
        components={"core":["core"],"funasr":["funasr"],"faster-whisper":["faster_whisper"],"all":["core","funasr","faster_whisper"]}[args.install_deps]
        index=envm.pip_index(); proxy=envm.proxy_for("pip")
        for req in envm.install_plan(components)["requirements"]:
            cmd=[sys.executable,"-m","pip","install","-r",str(BASE_DIR/req)]
            if index: cmd += ["--index-url",index]
            if proxy: cmd += ["--proxy",proxy]
            subprocess.check_call(cmd)
        print("Dependency installation completed.")
        return 0
    if args.self_test:
        ensure_core_dependencies(auto_install=False)
        return run_parent_self_test()
    ensure_core_dependencies(auto_install=False)
    if args.test_mode:
        os.environ["MEETINGAI_TEST_MODE"] = "1"
    setup_logging()
    logger = logging.getLogger(APP_NAME)
    try:
        RUNTIME = RuntimeContainer()
        setup_logging(RUNTIME.config)
        logger = logging.getLogger(APP_NAME)
        logger.info("%s %s starting in %s", APP_NAME, APP_VERSION, BASE_DIR)
        if any(report.values()):
            logger.info("Bootstrap report: %s", report)
        if RUNTIME.secrets.initial_password:
            print("\n" + "=" * 68)
            print(f"First-run administrator password: {RUNTIME.secrets.initial_password}")
            print(f"Also saved to: {FIRST_PASSWORD_PATH}")
            print("Change it after signing in.")
            print("=" * 68 + "\n")
        if args.reset_password:
            password = reset_admin_password()
            print(f"New administrator password: {password}")
            print(f"Saved to: {FIRST_PASSWORD_PATH}")
            return 0
        if args.internal_self_test:
            result = asyncio.run(run_internal_self_test(RUNTIME))
            print(json_dumps(result, pretty=True))
            return 0 if result.get("ok") else 1
        if args.doctor:
            async def doctor() -> Dict[str, Any]:
                await RUNTIME.start()
                try:
                    return await RUNTIME.diagnostics.full()
                finally:
                    await RUNTIME.stop()
            print(json_dumps(asyncio.run(doctor()), pretty=True))
            return 0

        import inspect
        import uvicorn
        app = create_app(RUNTIME)
        cfg = RUNTIME.config.get()
        requested_mode = "http" if args.http else ("https" if args.https else str(nested_get(cfg, "server.mode", "auto")))
        cert = (BASE_DIR / str(nested_get(cfg, "server.ssl_certfile", "ca.pem"))).resolve(); key = (BASE_DIR / str(nested_get(cfg, "server.ssl_keyfile", "ca.key"))).resolve()
        cert_ready = cert.exists() and key.exists()
        use_https = requested_mode != "http" and cert_ready
        degraded = requested_mode in {"auto", "https"} and not cert_ready
        if degraded:
            print("\n" + "=" * 72); print("WARNING: HTTPS certificate/key not found; MeetingAI is starting in HTTP fallback mode.")
            print(f"Expected: {cert} / {key}"); print("Remote browser microphone access may be blocked until HTTPS is available."); print("=" * 72 + "\n")
        host = args.host or str(nested_get(cfg, "server.host", "0.0.0.0")); public_port = args.port or int(nested_get(cfg, "server.https_port" if use_https else "server.port", 7778 if use_https else 7777)); scheme = "https" if use_https else "http"
        proxy_mode = str(nested_get(cfg, "server.proxy_mode", "direct")); uvicorn_host, uvicorn_port = host, public_port; shim = None
        if proxy_mode == "proxy_v2":
            uvicorn_host = "127.0.0.1"; uvicorn_port = find_free_loopback_port()
            shim = ProxyV2Shim(host, public_port, uvicorn_port, nested_get(cfg, "server.trusted_proxy_cidrs", []) or [], float(nested_get(cfg, "server.proxy_v2_header_timeout_seconds", 3.0)), int(nested_get(cfg, "server.proxy_v2_max_header_bytes", 512))); shim.start()
        display_host = "127.0.0.1" if host in {"0.0.0.0", "::"} else host
        root_path = str(nested_get(cfg, "server.root_path", "") or "")
        url = f"{scheme}://{display_host}:{public_port}{root_path}/"
        RUNTIME.transport = {"requested_mode": requested_mode, "scheme": scheme, "https": use_https, "degraded_to_http": degraded, "certificate_ready": cert_ready, "proxy_mode": proxy_mode, "public_port": public_port, "bind_host": host}
        kwargs: Dict[str, Any] = {"app": app, "host": uvicorn_host, "port": uvicorn_port, "log_level": "info", "proxy_headers": False,
            "access_log": True}
        if use_https: kwargs["ssl_certfile"] = str(cert); kwargs["ssl_keyfile"] = str(key)
        supported = inspect.signature(uvicorn.run).parameters
        kwargs = {k: v for k, v in kwargs.items() if k in supported}
        print(f"\n{APP_NAME} is available at: {url}")
        if proxy_mode == "proxy_v2": print(f"PROXY v2 listener: {host}:{public_port} -> internal 127.0.0.1:{uvicorn_port} (direct browser access to this listener is intentionally rejected)")
        if host in {"0.0.0.0", "::"}:
            lan_ips: List[str] = []
            with contextlib.suppress(Exception):
                for info in socket.getaddrinfo(socket.gethostname(), None, family=socket.AF_INET):
                    ip = str(info[4][0])
                    if ip and not ip.startswith("127.") and ip not in lan_ips:
                        lan_ips.append(ip)
            for ip in lan_ips[:8]:
                print(f"LAN address: {scheme}://{ip}:{public_port}/")
        auto_open = bool(nested_get(cfg, "server.auto_open_browser", False)) and not args.no_browser
        if auto_open:
            def open_later() -> None:
                time.sleep(1.2)
                with contextlib.suppress(Exception):
                    webbrowser.open(url)
            threading.Thread(target=open_later, daemon=True).start()
        uvicorn.run(**kwargs)
        return 0
    except KeyboardInterrupt:
        return 0
    except Exception as exc:
        logger.exception("Fatal startup error")
        print(f"Fatal error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
